PREPARE d_menu_stmt FROM @d_menu_guard;
EXECUTE d_menu_stmt;
DEALLOCATE PREPARE d_menu_stmt;
SET @d_menu_station=(SELECT id FROM station WHERE location_id=@d_menu_location AND name='周家粥铺' AND deleted_at IS NULL LIMIT 1);
INSERT INTO dish(station_id,name,price,price_unit,status) SELECT @d_menu_station,'猪肝粥',12.00,'份（估算演示价）',0 WHERE NOT EXISTS(SELECT 1 FROM dish WHERE station_id=@d_menu_station AND name='猪肝粥' AND deleted_at IS NULL);
