-- qishan-050 山东水饺
SET @d_menu_locations=(SELECT COUNT(*) FROM location WHERE name='山东水饺' AND address <=> '侯官路1-57号' AND deleted_at IS NULL);
SET @d_menu_guard=IF(@d_menu_locations=1,'DO 0','SELECT * FROM information_schema.D_MENU_LOCATION_NOT_UNIQUE');
PREPARE d_menu_stmt FROM @d_menu_guard;
EXECUTE d_menu_stmt;
DEALLOCATE PREPARE d_menu_stmt;
SET @d_menu_location=(SELECT id FROM location WHERE name='山东水饺' AND address <=> '侯官路1-57号' AND deleted_at IS NULL LIMIT 1);
INSERT INTO station(name,location_id) SELECT '山东水饺',@d_menu_location WHERE NOT EXISTS(SELECT 1 FROM station WHERE location_id=@d_menu_location AND name='山东水饺' AND deleted_at IS NULL);
SET @d_menu_stations=(SELECT COUNT(*) FROM station WHERE location_id=@d_menu_location AND name='山东水饺' AND deleted_at IS NULL);
SET @d_menu_guard=IF(@d_menu_stations=1,'DO 0','SELECT * FROM information_schema.D_MENU_STATION_NOT_UNIQUE');
PREPARE d_menu_stmt FROM @d_menu_guard;
EXECUTE d_menu_stmt;
DEALLOCATE PREPARE d_menu_stmt;
SET @d_menu_station=(SELECT id FROM station WHERE location_id=@d_menu_location AND name='山东水饺' AND deleted_at IS NULL LIMIT 1);
INSERT INTO dish(station_id,name,price,price_unit,status) SELECT @d_menu_station,'大葱水饺',12.00,'份（估算演示价）',0 WHERE NOT EXISTS(SELECT 1 FROM dish WHERE station_id=@d_menu_station AND name='大葱水饺' AND deleted_at IS NULL);
